_EVENT_FIELDS = """
fragment EventFields on Event {
  id name slug startAt isOnline numEntrants
  videogame { id }
}
"""

_TOURNAMENT_FIELDS = """
fragment TournamentFields on Tournament {
  id name slug startAt endAt city addrState countryCode venueName numAttendees isOnline
}
"""

_ENTRANT_FIELDS = """
fragment EntrantFields on Entrant {
  id name initialSeedNum isDisqualified
  participants { player { id gamerTag prefix } }
}
"""


def _with(query: str, *fragments: str) -> str:
    """A query document followed by the fragments it spreads"""
    return "".join([query, *fragments])


PLAYER = """
query Player($id: ID!) {
  player(id: $id) { id gamerTag prefix user { slug } }
}
"""

USER_PLAYER = """
query UserPlayer($slug: String!) {
  user(slug: $slug) { slug player { id gamerTag prefix } }
}
"""

VIDEOGAME = """
query Videogame($id: ID!) {
  videogame(id: $id) { id name characters { id name } stages { id name } }
}
"""

PLAYER_SETS = _with(
    """
query PlayerSets($id: ID!, $page: Int!, $perPage: Int!, $opponentId: ID, $filters: SetFilters) {
  player(id: $id) {
    id
    sets(page: $page, perPage: $perPage, opponentId: $opponentId, filters: $filters) {
      pageInfo { total totalPages page perPage }
      nodes {
        id completedAt fullRoundText round totalGames winnerId displayScore vodUrl state
        event { ...EventFields tournament { ...TournamentFields } }
        slots {
          entrant { ...EntrantFields }
          standing { placement stats { score { value } } }
        }
        games {
          orderNum winnerId entrant1Score entrant2Score
          stage { id name }
          selections { entrant { id } selectionType selectionValue }
        }
      }
    }
  }
}
""",
    _EVENT_FIELDS,
    _TOURNAMENT_FIELDS,
    _ENTRANT_FIELDS,
)

TOURNAMENTS = _with(
    """
query Tournaments($page: Int!, $perPage: Int!, $filter: TournamentPageFilter, $sortBy: String, $videogameIds: [ID]) {
  tournaments(query: {page: $page, perPage: $perPage, filter: $filter, sortBy: $sortBy}) {
    pageInfo { total totalPages page perPage }
    nodes { ...TournamentFields events(filter: {videogameId: $videogameIds}) { ...EventFields } }
  }
}
""",
    _TOURNAMENT_FIELDS,
    _EVENT_FIELDS,
)

EVENT_ENTRANTS = _with(
    """
query EventEntrants($id: ID, $slug: String, $page: Int!, $perPage: Int!) {
  event(id: $id, slug: $slug) {
    ...EventFields
    tournament { ...TournamentFields }
    entrants(query: {page: $page, perPage: $perPage}) {
      pageInfo { total totalPages page perPage }
      nodes { ...EntrantFields standing { placement } }
    }
  }
}
""",
    _EVENT_FIELDS,
    _TOURNAMENT_FIELDS,
    _ENTRANT_FIELDS,
)

EVENT_STANDINGS = _with(
    """
query EventStandings($id: ID, $slug: String, $page: Int!, $perPage: Int!) {
  event(id: $id, slug: $slug) {
    ...EventFields
    tournament { ...TournamentFields }
    standings(query: {page: $page, perPage: $perPage}) {
      pageInfo { total totalPages page perPage }
      nodes { placement entrant { ...EntrantFields } }
    }
  }
}
""",
    _EVENT_FIELDS,
    _TOURNAMENT_FIELDS,
    _ENTRANT_FIELDS,
)

CURRENT_USER_TOURNAMENTS = _with(
    """
query CurrentUserTournaments($perPage: Int!, $filter: UserTournamentsPaginationFilter, $videogameIds: [ID]) {
  currentUser {
    slug
    player { id gamerTag prefix }
    tournaments(query: {page: 1, perPage: $perPage, filter: $filter}) {
      pageInfo { total totalPages page perPage }
      nodes { ...TournamentFields events(filter: {videogameId: $videogameIds}) { ...EventFields } }
    }
  }
}
""",
    _TOURNAMENT_FIELDS,
    _EVENT_FIELDS,
)
